"use client";

import { useId, useRef, useState } from "react";
import type { CSSProperties, KeyboardEvent, ReactNode } from "react";
import { ChevronRight, File, Folder, FolderOpen } from "lucide-react";
import { AnimatePresence, motion, useIsPresent, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import { FluidHoverHighlight, useFluidHover } from "../lib/fluid-hover";
import styles from "./tree-view.module.css";

export interface TreeNode {
  id: string;
  label: string;
  children?: TreeNode[];
  icon?: ReactNode;
}

export interface TreeViewProps {
  nodes: TreeNode[];
  defaultExpandedIds?: string[];
  expandedIds?: string[];
  onExpandedChange?: (expandedIds: string[]) => void;
  onSelect?: (node: TreeNode) => void;
  "aria-label"?: string;
}

type VisibleNode = {
  node: TreeNode;
  depth: number;
  parentId?: string;
  position: number;
  setSize: number;
};

/** A row is 36px plus the 2px gap above it; both collapse together, so nothing snaps when a row leaves. */
const rowHeight = 38;
const still = { duration: 0 } as const;
const fadeIn = { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.enter] } as const;
const fadeOut = { duration: motionTokens.duration.instant, ease: [...motionTokens.ease.standard] } as const;
const blur = (px: number) => `blur(${px}px)`;

function flatten(nodes: TreeNode[], expanded: ReadonlySet<string>, depth = 1, parentId?: string): VisibleNode[] {
  return nodes.flatMap((node, index) => [
    { node, depth, parentId, position: index + 1, setSize: nodes.length },
    ...(node.children && expanded.has(node.id) ? flatten(node.children, expanded, depth + 1, node.id) : []),
  ]);
}

function fileTone(label: string, classNames: Record<string, string>) {
  const name = label.toLowerCase();
  if (name.endsWith(".tsx") || name.endsWith(".ts")) return classNames.typescript;
  if (name.endsWith(".css")) return classNames.stylesheet;
  if (name.endsWith(".md")) return classNames.markdown;
  if (name.endsWith(".json")) return classNames.json;
  return classNames.file;
}

/** Same markup with or without reduced motion, so the server render always hydrates cleanly; only the transition changes. */
function FolderIcon({ open, reduced }: { open: boolean; reduced: boolean }) {
  return <AnimatePresence initial={false} mode="popLayout">
    <motion.span
      key={open ? "open" : "closed"}
      className={styles.folderGlyph}
      initial={reduced ? false : { opacity: 0, scale: .6, filter: blur(motionTokens.blur.subtle) }}
      animate={{ opacity: 1, scale: 1, filter: blur(0) }}
      exit={reduced ? { opacity: 0, transition: still } : { opacity: 0, scale: .6, filter: blur(motionTokens.blur.subtle), transition: fadeOut }}
      transition={reduced ? still : { ...motionTokens.spring.snappy, opacity: fadeIn, filter: fadeIn }}
    >{open ? <FolderOpen size={16} strokeWidth={1.7} /> : <Folder size={16} strokeWidth={1.7} />}</motion.span>
  </AnimatePresence>;
}

/**
 * The selection fill glides between rows through a shared layoutId. A row that is leaving drops its fill at once: left
 * in place, it held the row's exit open, so the row stayed in the tree with pointer events off and the next click on it
 * after reopening its folder did nothing.
 */
function Selection({ layoutId, reduced }: { layoutId: string; reduced: boolean }) {
  const present = useIsPresent();
  if (!present) return null;
  return <motion.span aria-hidden="true" layoutId={layoutId} className={styles.selection} transition={reduced ? still : motionTokens.spring.morph} />;
}

export function TreeView({ nodes, defaultExpandedIds = [], expandedIds, onExpandedChange, onSelect, "aria-label": ariaLabel = "File tree" }: TreeViewProps) {
  const reduced = useReducedMotion() ?? false;
  const selectionLayoutId = `tree-selection-${useId()}`;
  const [internalExpanded, setInternalExpanded] = useState(() => new Set(defaultExpandedIds));
  const [focusedId, setFocusedId] = useState<string | null>(nodes[0]?.id ?? null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  /** The folder that opened last; its new children fade in one after another, then everything else stays still. */
  const [openedId, setOpenedId] = useState<string | null>(null);
  const refs = useRef(new Map<string, HTMLButtonElement>());
  const tree = useRef<HTMLDivElement>(null);
  // Fluid hover: the nearest row is lit, gaps and padding included, and keyboard focus moves the fill without travel.
  const hover = useFluidHover(tree, { items: '[role="treeitem"]' });
  const expanded = expandedIds ? new Set(expandedIds) : internalExpanded;
  const visible = flatten(nodes, expanded);
  const focusableId = visible.some(({ node }) => node.id === focusedId) ? focusedId : (visible[0]?.node.id ?? null);
  const openedIndex = visible.findIndex(({ node }) => node.id === openedId);

  function setExpanded(next: Set<string>) {
    if (!expandedIds) setInternalExpanded(next);
    onExpandedChange?.([...next]);
  }

  function toggle(node: TreeNode) {
    if (!node.children?.length) return;
    const next = new Set(expanded);
    if (next.has(node.id)) next.delete(node.id); else { next.add(node.id); setOpenedId(node.id); }
    setExpanded(next);
  }

  function focus(id: string) {
    setFocusedId(id);
    const row = refs.current.get(id);
    if (row) row.focus();
    else requestAnimationFrame(() => refs.current.get(id)?.focus());
  }

  function select(node: TreeNode) {
    setSelectedId(node.id);
    onSelect?.(node);
  }

  function onKeyDown(event: KeyboardEvent<HTMLButtonElement>, item: VisibleNode, index: number) {
    const { node } = item;
    if (event.key === "ArrowDown") { event.preventDefault(); focus(visible[Math.min(index + 1, visible.length - 1)]!.node.id); return; }
    if (event.key === "ArrowUp") { event.preventDefault(); focus(visible[Math.max(index - 1, 0)]!.node.id); return; }
    if (event.key === "Home") { event.preventDefault(); focus(visible[0]!.node.id); return; }
    if (event.key === "End") { event.preventDefault(); focus(visible[visible.length - 1]!.node.id); return; }
    if (event.key === "ArrowRight" && node.children?.length) {
      event.preventDefault();
      if (!expanded.has(node.id)) toggle(node);
      else if (visible[index + 1]?.parentId === node.id) focus(visible[index + 1]!.node.id);
      return;
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      if (node.children?.length && expanded.has(node.id)) toggle(node);
      else if (item.parentId) focus(item.parentId);
      return;
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      select(node);
      if (node.children?.length) toggle(node);
    }
  }

  return <div ref={tree} className={styles.tree} role="tree" aria-label={ariaLabel} aria-multiselectable="false" {...hover.handlers}>
    <FluidHoverHighlight hover={hover} className={styles.hover} />
    <AnimatePresence initial={false} mode="sync">
      {visible.map((item, index) => {
        const hasChildren = Boolean(item.node.children?.length);
        const isExpanded = hasChildren && expanded.has(item.node.id);
        const isSelected = selectedId === item.node.id;
        // Only rows that mount use this delay: the space opens in one motion and the new children follow in order.
        const delay = openedIndex >= 0 && index > openedIndex ? Math.min(index - openedIndex - 1, 7) * motionTokens.stagger.item : 0;
        return <motion.div
          key={item.node.id}
          className={styles.row}
          layout={reduced ? false : "position"}
          initial={reduced ? false : { height: 0, opacity: 0, x: -6, overflow: "hidden" }}
          animate={{ height: rowHeight, opacity: 1, x: 0, pointerEvents: "auto", transitionEnd: { overflow: "visible" }, transition: reduced ? still : { height: motionTokens.spring.smooth, opacity: { ...fadeIn, delay }, x: { ...motionTokens.spring.smooth, delay } } }}
          exit={reduced ? { opacity: 0, transition: still } : { height: 0, opacity: 0, x: -4, overflow: "hidden", pointerEvents: "none", transition: { height: motionTokens.spring.smooth, opacity: fadeOut, x: fadeOut } }}
          transition={reduced ? still : { layout: motionTokens.spring.smooth }}
        >
          <button
            ref={element => { if (element) refs.current.set(item.node.id, element); else refs.current.delete(item.node.id); }}
            type="button"
            className={styles.item}
            role="treeitem"
            aria-level={item.depth}
            aria-posinset={item.position}
            aria-setsize={item.setSize}
            aria-expanded={hasChildren ? isExpanded : undefined}
            aria-selected={isSelected}
            tabIndex={focusableId === item.node.id ? 0 : -1}
            style={{ "--tree-depth": item.depth } as CSSProperties}
            onFocus={() => setFocusedId(item.node.id)}
            onKeyDown={event => onKeyDown(event, item, index)}
            onClick={() => { setFocusedId(item.node.id); select(item.node); if (hasChildren) toggle(item.node); }}
          >
            {isSelected && <Selection layoutId={selectionLayoutId} reduced={reduced} />}
            {item.depth > 1 && <motion.span
              aria-hidden="true"
              className={styles.branch}
              initial={reduced ? false : { opacity: 0, scaleY: 0 }}
              animate={{ opacity: 1, scaleY: 1 }}
              transition={reduced ? still : { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter], delay }}
            />}
            <motion.span
              className={styles.disclosure}
              aria-hidden="true"
              initial={false}
              animate={{ rotate: isExpanded ? 90 : 0 }}
              transition={reduced ? still : motionTokens.spring.snappy}
            >{hasChildren ? <ChevronRight size={14} strokeWidth={1.9} /> : null}</motion.span>
            <span className={[styles.icon, hasChildren ? styles.folder : fileTone(item.node.label, styles)].join(" ")} aria-hidden="true">
              {item.node.icon ?? (hasChildren ? <FolderIcon open={isExpanded} reduced={reduced} /> : <File size={16} strokeWidth={1.7} />)}
            </span>
            <span className={styles.label}>{item.node.label}</span>
          </button>
        </motion.div>;
      })}
    </AnimatePresence>
  </div>;
}

export default TreeView;

.tree { position: relative; display: block; width: 100%; min-width: 0; box-sizing: border-box; padding: var(--space-related) var(--space-related) var(--space-related); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); overflow: hidden; }
/* Rows clip only while their height animates (Motion sets overflow), so the selection can glide between them unclipped. */
.row { position: relative; display: flow-root; min-width: 0; height: 38px; }
.item { position: relative; display: flex; width: 100%; min-width: 0; height: 36px; margin-top: var(--space-hair); align-items: center; gap: var(--space-related); padding: 0 var(--space-group); padding-left: calc(var(--space-group) + (var(--tree-depth) - 1) * var(--space-comfort)); border: 0; border-radius: var(--radius-detail); background: transparent; color: var(--text-secondary); font: inherit; font-size: var(--text-sm); line-height: 1; text-align: left; cursor: pointer; outline: none; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }
/* Selection changes color only; a heavier weight would reflow the label. */
.item[aria-selected="true"] { color: var(--foreground); }
/* One hover fill glides between rows, under the selection and the row content. */
.hover { border-radius: var(--radius-detail); background: var(--surface-muted); }
.selection { position: absolute; inset: 0; z-index: 0; border-radius: var(--radius-detail); background: var(--surface-muted); }
.branch { position: absolute; top: var(--space-tight); bottom: var(--space-tight); left: calc(var(--space-inset) + (var(--tree-depth) - 2) * var(--space-comfort)); z-index: 1; width: 1px; background: var(--border); transform-origin: top; pointer-events: none; }
.disclosure, .icon, .label { position: relative; z-index: 1; }
.disclosure { display: grid; width: 14px; height: 16px; flex: 0 0 14px; place-items: center; color: var(--text-muted); }
.icon { display: grid; width: 16px; height: 16px; flex: 0 0 16px; place-items: center; color: var(--text-muted); transition: color var(--duration-fast) var(--ease-standard); }
.folder { color: var(--text-secondary); }
.item[aria-expanded="true"] .folder, .item[aria-selected="true"] .folder { color: var(--foreground); }
.folderGlyph { position: absolute; inset: 0; display: grid; place-items: center; }
.typescript { color: color-mix(in oklab, var(--file-typescript) 78%, var(--foreground)); }
.stylesheet { color: color-mix(in oklab, var(--file-stylesheet) 73%, var(--foreground)); }
.markdown { color: color-mix(in oklab, var(--file-markdown) 74%, var(--foreground)); }
.json { color: color-mix(in oklab, var(--file-json) 78%, var(--foreground)); }
/* Its own line height: the row sets 1, and the clipped box (needed for the ellipsis) would cut descenders like g. */
.label { min-width: 0; overflow: hidden; line-height: 1.45; text-overflow: ellipsis; white-space: nowrap; }
@media (hover: hover) and (pointer: fine) { .item:hover { color: var(--foreground); } }
@media (prefers-reduced-motion: reduce) { .item, .icon { transition: none; } }

"use client";

/**
 * Fluid hover: in a set of items (a menu, a list, tabs, a grid), the item nearest the pointer is lit, even while the
 * pointer is in a gap, the padding or past the last item, and one highlight springs between items. A click in a gap goes
 * to the lit item, so what is lit is what a click hits. A new pointer entry fades the highlight in where it lands instead
 * of sliding it over from the last item. The keyboard moves it without travel, and reduced motion keeps the fade but
 * drops the travel.
 *
 *   const list = useRef<HTMLUListElement>(null);
 *   const hover = useFluidHover(list, { items: "[data-item]" });
 *   <ul ref={list} className={styles.list} {...hover.handlers}>      // .list { position: relative }
 *     <FluidHoverHighlight hover={hover} className={styles.highlight} />
 *     …items…
 *   </ul>
 *
 * Adapted from Fluid Functionalism's use-fluid-hover and fluid-hover-highlight by Micka Touillaud (MIT),
 * https://github.com/mickadesign/fluid-functionalism. Items are found by a selector instead of registering themselves,
 * so a component adopts it without changing its items.
 */
import { useEffect, useEffectEvent, useRef, useState } from "react";
import type { FocusEvent, MouseEvent, PointerEvent, RefObject } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "./motion-tokens";

/** An item's box in the container's own layout space (unaffected by transforms or scrolling). */
export interface FluidRect { top: number; left: number; width: number; height: number }

export interface FluidHoverState {
  /** Where the highlight sits, or null when nothing is lit. */
  rect: FluidRect | null;
  /** The lit item. */
  item: HTMLElement | null;
  /** False when the highlight should jump (keyboard, a resize) rather than travel. */
  glide: boolean;
  /** Steps on each new pointer entry, so the highlight fades in where it lands. */
  session: number;
}

export interface FluidHoverOptions {
  /** Selector for the items inside the container. */
  items: string;
  /** "y" for lists (default), "x" for a row of tabs, "xy" for grids. */
  axis?: "x" | "y" | "xy";
  /** Items the highlight skips (and a gap click never activates). Defaults to disabled or aria-disabled items. */
  isItemDisabled?: (item: HTMLElement) => boolean;
  /** "skip" (default) lights the nearest enabled item even over a disabled one; "clear" lights nothing over a disabled item (a calendar's unavailable days). */
  disabled?: "skip" | "clear";
  /** Route a click in a gap to the lit item. On by default; turn it off where empty space should stay inert. */
  gapClick?: boolean;
  /** Light the item that receives keyboard focus. On by default. */
  followFocus?: boolean;
}

const defaultDisabled = (item: HTMLElement) =>
  item.matches(":disabled, [aria-disabled='true'], [data-disabled]");

/** Controls that sit between items keep their own clicks. */
const CONTROL = "input, textarea, select, button, a, summary, [contenteditable], [role='textbox'], [role='searchbox'], [role='button']";

/** The item's box relative to the container, summing offsets through positioned ancestors in between. */
export function rectOf(item: HTMLElement, container: HTMLElement): FluidRect {
  let top = item.offsetTop, left = item.offsetLeft;
  let parent = item.offsetParent as HTMLElement | null;
  while (parent && parent !== container && container.contains(parent)) {
    top += parent.offsetTop + parent.clientTop;
    left += parent.offsetLeft + parent.clientLeft;
    parent = parent.offsetParent as HTMLElement | null;
  }
  return { top, left, width: item.offsetWidth, height: item.offsetHeight };
}

/**
 * The item the pointer is inside, or else the one whose edge is nearest along the axis (both axes for a grid). Edges, not
 * centres, so a gap next to a wide item still lights the item the pointer is closer to.
 */
export function pickNearest(items: HTMLElement[], x: number, y: number, axis: "x" | "y" | "xy"): HTMLElement | null {
  let nearest: HTMLElement | null = null, best = Infinity;
  for (const item of items) {
    const r = item.getBoundingClientRect();
    if (!r.width && !r.height) continue;
    if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) return item;
    const dx = Math.max(r.left - x, 0, x - r.right), dy = Math.max(r.top - y, 0, y - r.bottom);
    const distance = axis === "x" ? dx : axis === "y" ? dy : Math.hypot(dx, dy);
    if (distance < best) { best = distance; nearest = item; }
  }
  return nearest;
}

/** Hands a gap click to the item as a real mouse click (detail, modifiers and coordinates kept), so the item reads it as a pointer press, not a keyboard one. */
function forwardClick(item: HTMLElement, event: MouseEvent<HTMLElement>) {
  const { detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons } = event;
  item.dispatchEvent(new globalThis.MouseEvent("click", { bubbles: true, cancelable: true, composed: true, view: window, detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons }));
}

/** Whether an event happened inside the element whose handler hears it, not in a portalled child (a submenu, a tooltip). */
const isOwn = (event: { currentTarget: EventTarget; target: EventTarget }) =>
  !(event.currentTarget instanceof Node) || !(event.target instanceof Node) || event.currentTarget.contains(event.target);

export function useFluidHover<T extends HTMLElement>(container: RefObject<T | null>, options: FluidHoverOptions) {
  const { items: selector, axis = "y", isItemDisabled = defaultDisabled, disabled = "skip", gapClick = true, followFocus = true } = options;
  const [state, setState] = useState<FluidHoverState>({ rect: null, item: null, glide: false, session: 0 });
  const current = useRef(state);
  const pointer = useRef(false);
  const entering = useRef(false);
  const frame = useRef(0);

  function commit(next: FluidHoverState) {
    const prev = current.current;
    if (prev.item === next.item && prev.session === next.session && sameRect(prev.rect, next.rect)) return;
    current.current = next;
    setState(next);
  }

  function light(item: HTMLElement | null, glide: boolean) {
    const root = container.current;
    if (!root || !item) return commit({ ...current.current, rect: null, item: null, glide });
    let session = current.current.session;
    if (entering.current) { entering.current = false; session += 1; }
    commit({ rect: rectOf(item, root), item, glide: glide && session === current.current.session, session });
  }

  const enabledItems = () => {
    const root = container.current;
    return root ? [...root.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item)) : [];
  };

  // The lit item can move under a still highlight (a resize, content above it changing): follow it without travel.
  const follow = useEffectEvent(() => { const { item } = current.current; if (item?.isConnected) light(item, false); });
  useEffect(() => {
    const root = container.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => follow());
    observer.observe(root);
    return () => observer.disconnect();
  }, [container]);
  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const handlers = {
    onMouseEnter: () => { entering.current = true; },
    onMouseMove: (event: MouseEvent<T>) => {
      if (!isOwn(event)) return;
      pointer.current = true;
      const { clientX, clientY } = event;
      cancelAnimationFrame(frame.current);
      frame.current = requestAnimationFrame(() => {
        const over = disabled === "clear" ? document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(selector) : null;
        light(over && isItemDisabled(over) ? null : pickNearest(enabledItems(), clientX, clientY, axis), true);
      });
    },
    onMouseLeave: () => { cancelAnimationFrame(frame.current); entering.current = false; light(null, false); },
    onKeyDownCapture: () => { pointer.current = false; },
    onFocus: (event: FocusEvent<T>) => {
      if (!followFocus || pointer.current || !isOwn(event)) return;
      const item = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>(selector) : null;
      if (item && container.current?.contains(item) && !isItemDisabled(item)) light(item, false);
    },
    onBlur: (event: FocusEvent<T>) => {
      if (!pointer.current && !event.currentTarget.contains(event.relatedTarget as Node | null)) light(null, false);
    },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick || !isOwn(event)) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const { item } = current.current;
      if (item?.isConnected && !isItemDisabled(item)) forwardClick(item, event);
    },
  };

  /** Clears the highlight at once, such as when a menu opens again. */
  const reset = () => { cancelAnimationFrame(frame.current); entering.current = true; light(null, false); };

  return { ...state, handlers, reset, light };
}

export interface NearestItemOptions extends Omit<FluidHoverOptions, "followFocus"> {
  /** Called with the nearest enabled item as the mouse moves over the container. */
  onPick: (item: HTMLElement) => void;
}

/**
 * Fluid hover's picking without its highlight, for a list that already keeps its own active item and highlight (a listbox
 * with aria-activedescendant, a roving list): the mouse picks the nearest enabled item, gaps and padding included, and a
 * click in a gap goes to that item. Spread the result on the container.
 */
// A hook only so callbacks that touch refs can be passed during render; it keeps no state.
export function useNearestItem<T extends HTMLElement>({ items: selector, axis = "y", isItemDisabled = defaultDisabled, gapClick = true, onPick }: NearestItemOptions) {
  const nearest = (event: MouseEvent<T>) => {
    if (!isOwn(event)) return null;
    const items = [...event.currentTarget.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item));
    return pickNearest(items, event.clientX, event.clientY, axis);
  };
  return {
    onPointerMove: (event: PointerEvent<T>) => { if (event.pointerType !== "mouse") return; const item = nearest(event); if (item) onPick(item); },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const item = nearest(event);
      if (item) forwardClick(item, event);
    },
  };
}

const sameRect = (a: FluidRect | null, b: FluidRect | null) =>
  a === b || (!!a && !!b && a.top === b.top && a.left === b.left && a.width === b.width && a.height === b.height);

export interface FluidHoverHighlightProps {
  /** The state from useFluidHover (or any { rect, glide, session }). */
  hover: Pick<FluidHoverState, "rect" | "glide" | "session">;
  /** Radius, fill, z-index. The container must be position: relative; the highlight is placed at its top-left corner. */
  className?: string;
  /** Extra attributes for styling, such as data-tone. */
  tone?: string;
}

/** The one highlight a fluid hover set renders: it springs between items on transforms, and fades in and out. */
export function FluidHoverHighlight({ hover, className, tone }: FluidHoverHighlightProps) {
  const reduced = useReducedMotion() ?? false;
  const { rect, glide, session } = hover;
  const place = rect ? { x: rect.left, y: rect.top, width: rect.width, height: rect.height } : undefined;
  return (
    <AnimatePresence initial={false}>
      {place ? (
        <motion.span key={session} className={className} data-tone={tone} aria-hidden="true"
          style={{ position: "absolute", top: 0, left: 0, pointerEvents: "none" }}
          initial={{ opacity: 0, ...place }}
          animate={{ opacity: 1, ...place }}
          exit={{ opacity: 0, transition: motionTokens.spring.fast.exit }}
          transition={{ default: glide && !reduced ? motionTokens.spring.fast : { duration: 0 }, opacity: { duration: motionTokens.duration.fast } }} />
      ) : null}
    </AnimatePresence>
  );
}
